enum class UserCouponStatus(val label: String) {
      EXPIRED("EXPIRED"),
      RECEIVED("RECEIVED"),
      RETURNED("RETURNED"),
      USED("USED");

  companion object {
    @JvmStatic
    fun valueOfLabel(label: String): UserCouponStatus? {
      return values().find { it.label == label }
    }
  }
}

